INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_QU_CIV','The Qu — Architects of Flesh'),
 ('TXT_KEY_CWC3_QU_SHORT','The Qu'),
 ('TXT_KEY_CWC3_QU_ADJECTIVE','Qu'),
 ('TXT_KEY_CWC3_QU_LEADER','The First Architect'),
 ('TXT_KEY_CWC3_QU_TRAIT','Divine Reconfiguration'),
 ('TXT_KEY_CWC3_QU_TRAIT_HELP','Gain 1 Biomass from eligible enemy military kills (up to 3 per turn) and 2 when entering a new era. Store up to 10 Biomass. Spend 5 Biomass and 1 Population to install one genetic caste in an eligible annexed conquest. Open Genetic Reconfiguration with the Biomass button or from Additional Information.'),
 ('TXT_KEY_CWC3_QU_DAWN','First Architect, your people have crossed the spiral arms of the galaxy for ages. On each migration the Qu altered their own bodies, until life itself lay within their power. The law that once restrained that power now entrusts the future to your kind alone.[NEWLINE][NEWLINE]Below Genesis Spire lie worlds already shaped by other hands. Their inhabitants will defend the lives they know. Under your rule, their descendants will inherit bodies designed for purposes they never chose. Decide what this world will become before the Qu move on again.'),
 ('TXT_KEY_CWC3_QU_CIV_PEDIA','In C. M. Kösemen’s All Tomorrows, the Qu are an alien species nearly a billion years old. They migrate between the arms of the galaxy, altering their own bodies over the course of their travels. Their grasp of genetics and nanotechnology gives them the means to reshape entire worlds. A doctrine once meant to restrain their power hardens into a religious conviction that they alone have the right to determine what life will become.[NEWLINE][NEWLINE]When the Qu encounter the Star People, humanity’s descendants have already terraformed many worlds. The Qu regard this as a challenge to their mandate. They shatter the human civilizations in less than a thousand years and remake many survivors into animals, living tools, or experimental forms. After forty million years of rule, the Qu depart. Some altered human lineages survive and begin to evolve beyond the purposes their conquerors assigned them.'),
 ('TXT_KEY_CWC3_QU_CIV_STRATEGY','Build Gene Foundries in populous cities. After capturing a city, annex it, let resistance end, and build a Courthouse. Tailor the caste to its strongest yield. Labor Forms trade Science for Production, Cognitive Forms trade Production for Science, and Brood Forms trade Science for Food.'),
 ('TXT_KEY_CWC3_QU_LEADER_PEDIA','The First Architect is the mod’s imagined leader for the Qu expedition at Genesis Spire. The Architect treats a conquered population as the beginning of a lineage that will outlast its old civilization. The office and its seat were created for this adaptation of All Tomorrows.'),
 ('TXT_KEY_CWC3_QU_UNIT','Qu Harvester'),
 ('TXT_KEY_CWC3_QU_UNIT_HELP','Replaces the Rifleman and retains its active statistics and upgrade path. Biological Harvesting grants +15% Combat Strength against already-wounded enemy units and stays through upgrades.'),
 ('TXT_KEY_CWC3_QU_UNIT_PEDIA','Harvesters represent the expedition’s field specialists. In flight, a Harvester controls its instruments with the same long tail it uses to manipulate other objects. It follows the traces of earlier engagements to find weakened opponents.'),
 ('TXT_KEY_CWC3_QU_UNIT_STRATEGY','Soften enemy units before committing Harvesters. Capture ground with their ordinary Rifleman movement and retain the promotion as they upgrade.'),
 ('TXT_KEY_CWC3_QU_PROMOTION','Biological Harvesting'),
 ('TXT_KEY_CWC3_QU_PROMOTION_HELP','+15% Combat Strength when attacking or defending against an enemy unit already wounded at the start of combat. Retained on upgrade.'),
 ('TXT_KEY_CWC3_QU_BUILDING','Gene Foundry'),
 ('TXT_KEY_CWC3_QU_BUILDING_HELP','Replaces the Workshop and retains its effects. Provides +1 base [ICON_RESEARCH] Science at Population 5–9 and +2 at Population 10 or higher.'),
 ('TXT_KEY_CWC3_QU_BUILDING_PEDIA','The Qu leave enormous pyramids on inhabited worlds they pass through. The Gene Foundry adapts that landmark into a workshop and research center. Within its sealed galleries, the Qu keep living collections and record the lineages they have reshaped.'),
 ('TXT_KEY_CWC3_QU_BUILDING_STRATEGY','Build Gene Foundries wherever you would build Workshops. Growing a Foundry city to Population 5 or 10 increases its base Science.'),
 ('TXT_KEY_CWC3_QU_LABOR','Labor Forms'),
 ('TXT_KEY_CWC3_QU_COGNITIVE','Cognitive Forms'),
 ('TXT_KEY_CWC3_QU_BROOD','Brood Forms'),
 ('TXT_KEY_CWC3_QU_LABOR_EFFECT','+12% [ICON_PRODUCTION] Production, −10% [ICON_RESEARCH] Science'),
 ('TXT_KEY_CWC3_QU_COGNITIVE_EFFECT','+12% [ICON_RESEARCH] Science, −10% [ICON_PRODUCTION] Production'),
 ('TXT_KEY_CWC3_QU_BROOD_EFFECT','+15% [ICON_FOOD] Food, −10% [ICON_RESEARCH] Science'),
 ('TXT_KEY_CWC3_QU_FOUNDRY_EFFECT','Gene Foundry Population Science'),
 ('TXT_KEY_CWC3_QU_OPEN','Genetic Reconfiguration'),
 ('TXT_KEY_CWC3_QU_BIOMASS','Biomass {1_Num}/{2_Num}'),
 ('TXT_KEY_CWC3_QU_COST','Each caste costs {1_Num} Biomass and {2_Num} Population.'),
 ('TXT_KEY_CWC3_QU_CITY_STATUS','{1_City} • Population {2_Num}'),
 ('TXT_KEY_CWC3_QU_CITY_COUNT','{1_Num} of {2_Num}'),
 ('TXT_KEY_CWC3_QU_NO_CITY','No city available.'),
 ('TXT_KEY_CWC3_QU_NO_CONQUEST','Requires a city gained by military conquest.'),
