 ('TXT_KEY_CWC3_QU_CHANGED','The selected conquest has changed. Choose a city again.'),
 ('TXT_KEY_CWC3_QU_CONFIRM','Install {1_Caste} in {2_City}? This spends {3_Num} Biomass and {4_Num} Population.'),
